'use strict';

const { PAYLOAD_KEYS, HOST_PATTERNS, SSE_URL_MARKER } = require('./constants');

/**
 * Flattens the API's responses into one predictable shape.
 *
 * Two things vary between endpoints and are smoothed over here:
 *   - the payload wrapper key (`data` on most, `answer` on a few)
 *   - the duration unit (seconds, milliseconds, or an "mm:ss" string)
 */

const AUDIO_EXTENSIONS = /\.(mp3|m4a|aac|opus|ogg|wav|flac)(\?|$)/i;
const IMAGE_EXTENSIONS = /\.(jpe?g|png|webp|gif|heic|avif)(\?|$)/i;
const VIDEO_EXTENSIONS = /\.(mp4|mov|webm|mkv|m4v|avi)(\?|$)/i;

// Sources observed to report duration in milliseconds rather than seconds.
const MILLISECOND_SOURCES = new Set(['tiktok', 'facebook', 'douyin', 'instagram']);

// Above this, a "seconds" value is almost certainly milliseconds (10 hours).
const MILLISECOND_THRESHOLD = 36000;

/** Pull the payload out of the response envelope. */
function unwrap(body) {
  if (!body || typeof body !== 'object') return null;

  for (const key of PAYLOAD_KEYS) {
    if (body[key] && typeof body[key] === 'object') return body[key];
  }
  return body;
}

/** Label the platform from the URL host. Routing does not depend on this. */
function detectPlatform(url) {
  let host;
  try {
    host = new URL(String(url)).hostname.toLowerCase().replace(/^www\./, '');
  } catch {
    return 'unknown';
  }

  for (const [platform, hosts] of HOST_PATTERNS) {
    if (hosts.some((candidate) => host === candidate || host.endsWith(`.${candidate}`))) {
      return platform;
    }
  }
  return 'unknown';
}

function isHttpUrl(value) {
  return typeof value === 'string' && /^https?:\/\//i.test(value.trim());
}

function guessType(url, fallback = 'video') {
  if (AUDIO_EXTENSIONS.test(url)) return 'audio';
  if (IMAGE_EXTENSIONS.test(url)) return 'image';
  if (VIDEO_EXTENSIONS.test(url)) return 'video';
  return fallback;
}

/**
 * Convert whatever the API sent into seconds.
 *
 * Observed formats: 213 (seconds), "3:33" (mm:ss), "00:03:33" (hh:mm:ss),
 * 24564 (milliseconds, on TikTok), null.
 *
 * Millisecond detection leans on the `source` field first and falls back to a
 * magnitude check, so a genuinely long video is not mistaken for milliseconds.
 */
function parseDuration(value, source = '') {
  if (value === null || value === undefined || value === '') return null;

  if (typeof value === 'string') {
    const text = value.trim();

    if (/^\d{1,3}(:\d{1,2}){1,2}$/.test(text)) {
      return text.split(':').map(Number).reduce((total, part) => total * 60 + part, 0);
    }

    const numeric = Number(text);
    if (!Number.isFinite(numeric)) return null;
    return normalizeSeconds(numeric, source);
  }

  if (typeof value === 'number' && Number.isFinite(value)) {
    return normalizeSeconds(value, source);
  }

  return null;
}

function normalizeSeconds(value, source) {
  const platform = String(source || '').toLowerCase();
  const looksLikeMilliseconds =
    [...MILLISECOND_SOURCES].some((name) => platform.includes(name)) || value >= MILLISECOND_THRESHOLD;

  return looksLikeMilliseconds && value >= 1000 ? Math.round(value / 1000) : Math.round(value);
}

function addMedia(list, seen, url, type, extra = {}) {
  if (!isHttpUrl(url)) return;

  const clean = url.trim();
  if (seen.has(clean)) return;
  seen.add(clean);

  list.push({
    type,
    url: clean,
    // True when the link streams encoding progress and must be resolved first.
    pending: clean.includes(SSE_URL_MARKER),
    ...extra,
  });
}

const VIDEO_KEYS = ['downloadLink', 'videoUrl', 'video_url', 'play', 'hdplay', 'downloadUrl', 'directUrl'];
const AUDIO_KEYS = ['mp3DownloadLink', 'music', 'audioUrl', 'audio_url', 'mp3'];
const TITLE_KEYS = ['title', 'description', 'desc', 'text', 'caption', 'name'];
const AUTHOR_KEYS = ['author', 'nickname', 'uploader', 'channel', 'username', 'owner'];
const THUMB_KEYS = ['thumbnail', 'thumb', 'cover', 'poster', 'image', 'profilePic'];

function firstString(payload, keys) {
  for (const key of keys) {
    const value = payload[key];
    if (typeof value === 'string' && value.trim() !== '') return value.trim();
    if (value && typeof value === 'object' && typeof value.name === 'string') return value.name;
  }
  return null;
}

function firstUrl(payload, keys) {
  for (const key of keys) {
    if (isHttpUrl(payload[key])) return payload[key].trim();
  }
  return null;
}

/** Read the `attachment` array, which is what downallv2 returns. */
function collectFromAttachment(payload, list, seen) {
  if (!Array.isArray(payload.attachment)) return;

  for (const item of payload.attachment) {
    if (!item) continue;

    const declared = String(item.type || '').toLowerCase();
    const type = declared === 'photo' ? 'image' : declared === 'audio' ? 'audio' : 'video';

    addMedia(list, seen, item.url, type, { quality: item.quality || null });
  }
}

/** Read the `formats` object shape used by youtubedl. */
function collectFromFormatsObject(payload, list, seen) {
  const formats = payload.formats;
  if (!formats || typeof formats !== 'object' || Array.isArray(formats)) return;

  for (const [kind, format] of Object.entries(formats)) {
    if (!format || typeof format !== 'object') continue;

    addMedia(list, seen, format.directUrl || format.url, kind === 'audio' ? 'audio' : 'video', {
      quality: format.quality || null,
      mimeType: format.mimeType || null,
      filesize: format.filesize ? Number(format.filesize) : null,
    });
  }
}

/** Read generic arrays some endpoints use instead. */
function collectFromArrays(payload, list, seen) {
  for (const array of [payload.medias, payload.media, payload.images, payload.urls, payload.links]) {
    if (!Array.isArray(array)) continue;

    for (const item of array) {
      if (isHttpUrl(item)) {
        addMedia(list, seen, item, guessType(item));
        continue;
      }
      if (!item || typeof item !== 'object') continue;

      const url = item.resource_url || item.url || item.downloadUrl || item.link;
      if (!isHttpUrl(url)) continue;

      const declared = String(item.media_type || item.type || item.kind || '').toLowerCase();
      const type =
        declared === 'audio'
          ? 'audio'
          : declared === 'image' || declared === 'photo'
            ? 'image'
            : declared === 'video'
              ? 'video'
              : guessType(url);

      addMedia(list, seen, url, type, {
        quality: item.quality || item.label || null,
        extension: item.extension || item.ext || null,
      });
    }
  }
}

/**
 * Normalize one API response.
 *
 * @returns {{ok: boolean, platform: string, sourceUrl: string, endpoint: string,
 *   title: string|null, author: string|null, thumbnail: string|null,
 *   duration: number|null, durationRaw: unknown, media: object[],
 *   video: string|null, audio: string|null, images: string[], raw: object}}
 */
function normalize(body, { sourceUrl, endpoint }) {
  const payload = unwrap(body) || {};
  const media = [];
  const seen = new Set();

  collectFromAttachment(payload, media, seen);
  collectFromFormatsObject(payload, media, seen);
  collectFromArrays(payload, media, seen);

  for (const key of VIDEO_KEYS) addMedia(media, seen, payload[key], 'video');
  for (const key of AUDIO_KEYS) addMedia(media, seen, payload[key], 'audio');

  const source = payload.source || payload.platform || detectPlatform(sourceUrl);
  const rawDuration = payload.duration ?? payload.durationSeconds ?? payload.lengthSeconds ?? null;

  const video = media.find((item) => item.type === 'video') || null;
  const audio = media.find((item) => item.type === 'audio') || null;

  return {
    ok: media.length > 0,
    platform: source,
    sourceUrl,
    endpoint,
    title: firstString(payload, TITLE_KEYS),
    author: firstString(payload, AUTHOR_KEYS),
    thumbnail: firstUrl(payload, THUMB_KEYS),
    duration: parseDuration(rawDuration, source),
    // Kept so callers can apply their own interpretation if needed.
    durationRaw: rawDuration,
    media,
    video: video ? video.url : null,
    audio: audio ? audio.url : null,
    images: media.filter((item) => item.type === 'image').map((item) => item.url),
    raw: payload,
  };
}

module.exports = { normalize, unwrap, detectPlatform, guessType, isHttpUrl, parseDuration };
